This word search marks visited cells with `#` but forgets to restore them. What does it return?

```python
def exist(board, word):
    R, C = len(board), len(board[0])
    def dfs(r, c, k):
        if k == len(word):
            return True
        if r < 0 or c < 0 or r >= R or c >= C or board[r][c] != word[k]:
            return False
        board[r][c] = "#"
        return (dfs(r + 1, c, k + 1) or dfs(r - 1, c, k + 1)
                or dfs(r, c + 1, k + 1) or dfs(r, c - 1, k + 1))
    return any(dfs(r, c, 0) for r in range(R) for c in range(C))

board = [list("CAA"), list("AAA"), list("BCD")]
print(exist(board, "AAB"))
```

